#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <signal.h>

#define MAX_MSG_SIZE 1024
#define MAX_TOPICS 64
#define DEVICE_PORT 8883

typedef struct {
    char *topic;
    char *payload;
    int qos;
    void (*handler)(const char *payload, int len);
} mqtt_subscription_t;

typedef struct {
    mqtt_subscription_t *subscriptions[MAX_TOPICS];
    int sub_count;
    int sock_fd;
    char device_id[32];
} iot_device_ctx_t;

static iot_device_ctx_t *g_ctx = NULL;

void telemetry_handler(const char *payload, int len) {
    printf("[TELEMETRY] Received %d bytes\n", len);
}

void command_handler(const char *payload, int len) {
    // Execute device command from payload
    if (len > 0 && payload != NULL) {
        char cmd_buf[256];
        snprintf(cmd_buf, sizeof(cmd_buf), "/bin/sh -c '%.*s'", len, payload);
        system(cmd_buf);  // Remote command execution via MQTT command topic
    }
}

void ota_handler(const char *payload, int len) {
    printf("[OTA] Update notification: %.*s\n", len, payload);
}

mqtt_subscription_t* find_subscription(iot_device_ctx_t *ctx, const char *topic) {
    if (!ctx) return NULL;
    for (int i = 0; i < ctx->sub_count; i++) {
        if (ctx->subscriptions[i] && 
            strcmp(ctx->subscriptions[i]->topic, topic) == 0) {
            return ctx->subscriptions[i];
        }
    }
    return NULL;
}

// VULNERABILITY: No null check on subscription lookup result before dereferencing handler
void dispatch_message(iot_device_ctx_t *ctx, const char *topic, const char *payload, int len) {
    mqtt_subscription_t *sub = find_subscription(ctx, topic);

    // BUG: sub could be NULL if topic not found, leading to null pointer dereference
    // An attacker can craft a message to an unsubscribed topic to crash the device
    // OR if they control the handler pointer via memory corruption, redirect execution
    sub->handler(payload, len);  // NULL dereference if topic not in subscription list
}

void process_incoming(iot_device_ctx_t *ctx) {
    char buffer[MAX_MSG_SIZE];
    struct sockaddr_in client_addr;
    socklen_t addr_len = sizeof(client_addr);

    int bytes = recvfrom(ctx->sock_fd, buffer, MAX_MSG_SIZE - 1, 0,
                         (struct sockaddr*)&client_addr, &addr_len);
    if (bytes <= 0) return;
    buffer[bytes] = '\0';

    // Simple protocol: TOPIC|PAYLOAD
    char *sep = strchr(buffer, '|');
    if (!sep) return;
    *sep = '\0';

    char *topic = buffer;
    char *payload = sep + 1;
    int payload_len = bytes - (payload - buffer);

    dispatch_message(ctx, topic, payload, payload_len);
}

int init_device(const char *device_id) {
    g_ctx = (iot_device_ctx_t*)calloc(1, sizeof(iot_device_ctx_t));
    if (!g_ctx) return -1;

    strncpy(g_ctx->device_id, device_id, sizeof(g_ctx->device_id) - 1);

    g_ctx->sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (g_ctx->sock_fd < 0) return -1;

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(DEVICE_PORT);
    addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(g_ctx->sock_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) return -1;

    // Register default subscriptions
    mqtt_subscription_t *telem = calloc(1, sizeof(mqtt_subscription_t));
    telem->topic = strdup("device/telemetry");
    telem->handler = telemetry_handler;
    g_ctx->subscriptions[g_ctx->sub_count++] = telem;

    mqtt_subscription_t *cmd = calloc(1, sizeof(mqtt_subscription_t));
    cmd->topic = strdup("device/command");
    cmd->handler = command_handler;
    g_ctx->subscriptions[g_ctx->sub_count++] = cmd;

    mqtt_subscription_t *ota = calloc(1, sizeof(mqtt_subscription_t));
    ota->topic = strdup("device/ota");
    ota->handler = ota_handler;
    g_ctx->subscriptions[g_ctx->sub_count++] = ota;

    return 0;
}

int main(int argc, char *argv[]) {
    if (init_device("sensor-node-0x4A") < 0) {
        fprintf(stderr, "Device init failed\n");
        return 1;
    }

    printf("IoT device [%s] listening on port %d\n", g_ctx->device_id, DEVICE_PORT);

    while (1) {
        process_incoming(g_ctx);
    }

    return 0;
}
